insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('jer-43-3','jer','예레미야',43,3,'이는 네리야의 아들 바룩이 너를 부추겨서 우리를 대적하여 갈대아 사람의 손에 넘겨 죽이며 바벨론으로 붙잡아가게 하려 함이라',20001),
('jer-43-4','jer','예레미야',43,4,'이에 가레아의 아들 요하난과 모든 군 지휘관과 모든 백성이 유다 땅에 살라 하시는 여호와의 목소리를 순종하지 아니하고',20002),
('jer-43-5','jer','예레미야',43,5,'가레아의 아들 요하난과 모든 군 지휘관이 유다의 남은 자 곧 쫓겨났던 여러 나라 가운데에서 유다 땅에 살려 하여 돌아온 자',20003),
('jer-43-6','jer','예레미야',43,6,'곧 남자와 여자와 유아와 왕의 딸들과 사령관 느부사라단이 사반의 손자 아히감의 아들 그다랴에게 맡겨 둔 모든 사람과 선지자 예레미야와 네리야의 아들 바룩을 거느리고',20004),
('jer-43-7','jer','예레미야',43,7,'애굽 땅에 들어가 다바네스에 이르렀으니 그들이 여호와의 목소리를 순종하지 아니함이러라',20005),
('jer-43-8','jer','예레미야',43,8,'다바네스에서 여호와의 말씀이 예레미야에게 임하여 이르시되',20006),
('jer-43-9','jer','예레미야',43,9,'너는 유다 사람의 눈 앞에서 네 손으로 큰 돌 여러 개를 가져다가 다바네스에 있는 바로의 궁전 대문의 벽돌로 쌓은 축대에 진흙으로 감추라',20007),
('jer-43-10','jer','예레미야',43,10,'그리고 너는 그들에게 말하기를 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 보라 내가 내 종 바벨론의 느부갓네살 왕을 불러오리니 그가 그의 왕좌를 내가 감추게 한 이 돌들 위에 놓고 또 그 화려한 큰 장막을 그 위에 치리라',20008),
('jer-43-11','jer','예레미야',43,11,'그가 와서 애굽 땅을 치고 죽일 자는 죽이고 사로잡을 자는 사로잡고 칼로 칠 자는 칼로 칠 것이라',20009),
('jer-43-12','jer','예레미야',43,12,'내가 애굽 신들의 신당들을 불지르리라 느부갓네살이 그들을 불사르며 그들을 사로잡을 것이요 목자가 그의 몸에 옷을 두름 같이 애굽 땅을 자기 몸에 두르고 평안히 그 곳을 떠날 것이며',20010),
('jer-43-13','jer','예레미야',43,13,'그가 또 애굽 땅 벧세메스의 석상들을 깨뜨리고 애굽 신들의 신당들을 불사르리라 하셨다 할지니라 하니라',20011),
('jer-44-1','jer','예레미야',44,1,'애굽 땅에 사는 모든 유다 사람 곧 믹돌과 다바네스와 놉과 바드로스 지방에 사는 자에 대하여 말씀이 예레미야에게 임하니라 이르시되',20012),
('jer-44-2','jer','예레미야',44,2,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 너희가 예루살렘과 유다 모든 성읍에 내린 나의 모든 재난을 보았느니라 보라 오늘 그것들이 황무지가 되었고 사는 사람이 없나니',20013),
('jer-44-3','jer','예레미야',44,3,'이는 그들이 자기나 너희나 너희 조상들이 알지 못하는 다른 신들에게 나아가 분향하여 섬겨서 나의 노여움을 일으킨 악행으로 말미암음이라',20014),
('jer-44-4','jer','예레미야',44,4,'내가 나의 모든 종 선지자들을 너희에게 보내되 끊임없이 보내어 이르기를 너희는 내가 미워하는 이 가증한 일을 행하지 말라 하였으나',20015),
('jer-44-5','jer','예레미야',44,5,'그들이 듣지 아니하며 귀를 기울이지 아니하고 다른 신들에게 여전히 분향하여 그들의 악에서 돌이키지 아니하였으므로',20016),
('jer-44-6','jer','예레미야',44,6,'나의 분과 나의 노여움을 쏟아서 유다 성읍들과 예루살렘 거리를 불살랐더니 그것들이 오늘과 같이 폐허와 황무지가 되었느니라',20017),
('jer-44-7','jer','예레미야',44,7,'만군의 하나님 이스라엘의 하나님 여호와께서 이와 같이 말씀하셨느니라 너희가 어찌하여 큰 악을 행하여 자기 영혼을 해하며 유다 가운데에서 너희의 남자와 여자와 아이와 젖 먹는 자를 멸절하여 남은 자가 없게 하려느냐',20018),
('jer-44-8','jer','예레미야',44,8,'어찌하여 너희가 너희 손이 만든 것으로 나의 노여움을 일으켜 너희가 가서 머물러 사는 애굽 땅에서 다른 신들에게 분향함으로 끊어 버림을 당하여 세계 여러 나라 가운데에서 저주와 수치 거리가 되고자 하느냐',20019),
('jer-44-9','jer','예레미야',44,9,'너희가 유다 땅과 예루살렘 거리에서 행한 너희 조상들의 악행과 유다 왕들의 악행과 왕비들의 악행과 너희의 악행과 너희 아내들의 악행을 잊었느냐',20020),
('jer-44-10','jer','예레미야',44,10,'그들이 오늘까지 겸손하지 아니하며 두려워하지도 아니하고 내가 너희와 너희 조상들 앞에 세운 나의 율법과 나의 법규를 지켜 행하지 아니하느니라',20021),
('jer-44-11','jer','예레미야',44,11,'그러므로 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 보라 내가 얼굴을 너희에게로 향하여 환난을 내리고 온 유다를 끊어 버릴 것이며',20022),
('jer-44-12','jer','예레미야',44,12,'내가 또 애굽 땅에 머물러 살기로 고집하고 그리로 들어간 유다의 남은 자들을 처단하리니 그들이 다 멸망하여 애굽 땅에서 엎드러질 것이라 그들이 칼과 기근에 망하되 낮은 자로부터 높은 자까지 칼과 기근에 죽어서 저주와 놀램과 조롱과 수치의 대상이 되리라',20023),
('jer-44-13','jer','예레미야',44,13,'내가 예루살렘을 벌한 것 같이 애굽 땅에 사는 자들을 칼과 기근과 전염병으로 벌하리니',20024),
('jer-44-14','jer','예레미야',44,14,'애굽 땅에 들어가서 거기에 머물러 살려는 유다의 남은 자 중에 피하거나 살아 남아 소원대로 돌아와서 살고자 하여 유다 땅에 돌아올 자가 없을 것이라 도망치는 자들 외에는 돌아올 자가 없으리라 하셨느니라',20025),
('jer-44-15','jer','예레미야',44,15,'그리하여 자기 아내들이 다른 신들에게 분향하는 줄을 아는 모든 남자와 곁에 섰던 모든 여인 곧 애굽 땅 바드로스에 사는 모든 백성의 큰 무리가 예레미야에게 대답하여 이르되',20026),
('jer-44-16','jer','예레미야',44,16,'네가 여호와의 이름으로 우리에게 하는 말을 우리가 듣지 아니하고',20027),
('jer-44-17','jer','예레미야',44,17,'우리 입에서 낸 모든 말을 반드시 실행하여 우리가 본래 하던 것 곧 우리와 우리 선조와 우리 왕들과 우리 고관들이 유다 성읍들과 예루살렘 거리에서 하던 대로 하늘의 여왕에게 분향하고 그 앞에 전제를 드리리라 그 때에는 우리가 먹을 것이 풍부하며 복을 받고 재난을 당하지 아니하였더니',20028),
('jer-44-18','jer','예레미야',44,18,'우리가 하늘의 여왕에게 분향하고 그 앞에 전제 드리던 것을 폐한 후부터는 모든 것이 궁핍하고 칼과 기근에 멸망을 당하였느니라 하며',20029),
('jer-44-19','jer','예레미야',44,19,'여인들은 이르되 우리가 하늘의 여왕에게 분향하고 그 앞에 전제를 드릴 때에 어찌 우리 남편의 허락이 없이 그의 형상과 같은 과자를 만들어 놓고 전제를 드렸느냐 하는지라',20030),
('jer-44-20','jer','예레미야',44,20,'예레미야가 남녀 모든 무리 곧 이 말로 대답하는 모든 백성에게 일러 이르되',20031),
('jer-44-21','jer','예레미야',44,21,'너희가 너희 선조와 너희 왕들과 고관들과 유다 땅 백성이 유다 성읍들과 예루살렘 거리에서 분향한 일을 여호와께서 기억하셨고 그의 마음에 떠오른 것이 아닌가',20032),
('jer-44-22','jer','예레미야',44,22,'여호와께서 너희 악행과 가증한 행위를 더 참을 수 없으셨으므로 너희 땅이 오늘과 같이 황폐하며 놀램과 저줏거리가 되어 주민이 없게 되었나니',20033),
('jer-44-23','jer','예레미야',44,23,'너희가 분향하여 여호와께 범죄하였으며 여호와의 목소리를 순종하지 아니하고 여호와의 율법과 법규와 여러 증거대로 행하지 아니하였으므로 이 재난이 오늘과 같이 너희에게 일어났느니라',20034),
('jer-44-24','jer','예레미야',44,24,'예레미야가 다시 모든 백성과 모든 여인에게 말하되 애굽 땅에서 사는 모든 유다 사람이여 여호와의 말씀을 들으라',20035),
('jer-44-25','jer','예레미야',44,25,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 너희와 너희 아내들이 입으로 말하고 손으로 이루려 하여 이르기를 우리가 서원한 대로 반드시 이행하여 하늘의 여왕에게 분향하고 전제를 드리리라 하였은즉 너희 서원을 성취하며 너희 서원을 이행하라 하시느니라',20036),
('jer-44-26','jer','예레미야',44,26,'그러므로 애굽 땅에서 사는 모든 유다 사람이여 여호와의 말씀을 들으라 여호와께서 말씀하시되 보라 내가 나의 큰 이름으로 맹세하였은즉 애굽 온 땅에 사는 유다 사람들의 입에서 다시는 내 이름을 부르며 주 여호와의 살아 계심을 두고 맹세하노라 하는 자가 없으리라',20037),
('jer-44-27','jer','예레미야',44,27,'보라 내가 깨어 있어 그들에게 재난을 내리고 복을 내리지 아니하리니 애굽 땅에 있는 유다 모든 사람이 칼과 기근에 망하여 멸절되리라',20038),
('jer-44-28','jer','예레미야',44,28,'그런즉 칼을 피한 소수의 사람이 애굽 땅에서 나와 유다 땅으로 돌아오리니 애굽 땅에 들어가서 거기에 머물러 사는 유다의 모든 남은 자가 내 말과 그들의 말 가운데서 누구의 말이 진리인지 알리라',20039),
('jer-44-29','jer','예레미야',44,29,'여호와의 말씀이니라 내가 이 곳에서 너희를 벌할 표징이 이것이라 내가 너희에게 재난을 내리리라 한 말이 반드시 이루어질 것을 그것으로 알게 하리라',20040),
('jer-44-30','jer','예레미야',44,30,'보라 내가 유다의 시드기야 왕을 그의 원수 곧 그의 생명을 찾는 바벨론의 느부갓네살 왕의 손에 넘긴 것 같이 애굽의 바로 호브라 왕을 그의 원수들 곧 그의 생명을 찾는 자들의 손에 넘겨 주리라 여호와께서 이와 같이 말씀하셨느니라',20041),
('jer-45-1','jer','예레미야',45,1,'유다의 요시야 왕의 아들 여호야김 넷째 해에 네리야의 아들 바룩이 예레미야가 불러 주는 대로 이 모든 말을 책에 기록하니라 그 때에 선지자 예레미야가 그에게 말하여 이르되',20042),
('jer-45-2','jer','예레미야',45,2,'바룩아 이스라엘의 하나님 여호와께서 네게 이같이 말씀하셨느니라',20043),
('jer-45-3','jer','예레미야',45,3,'네가 일찍이 말하기를 화로다 여호와께서 나의 고통에 슬픔을 더하셨으니 나는 나의 탄식으로 피곤하여 평안을 찾지 못하도다',20044),
('jer-45-4','jer','예레미야',45,4,'너는 그에게 이르라 여호와께서 이와 같이 말씀하시기를 보라 나는 내가 세운 것을 헐기도 하며 내가 심은 것을 뽑기도 하나니 온 땅에 그리하겠거늘',20045),
('jer-45-5','jer','예레미야',45,5,'네가 너를 위하여 큰 일을 찾느냐 그것을 찾지 말라 보라 내가 모든 육체에 재난을 내리리라 그러나 네가 가는 모든 곳에서는 내가 너에게 네 생명을 노략물 주듯 하리라 여호와의 말씀이니라',20046),
('jer-46-1','jer','예레미야',46,1,'이방 나라들에 대하여 선지자 예레미야에게 임한 여호와의 말씀이라',20047),
('jer-46-2','jer','예레미야',46,2,'애굽에 관한 것이라 곧 유다의 요시야 왕의 아들 여호야김 넷째 해에 유브라데 강 가 갈그미스에서 바벨론의 느부갓네살 왕에게 패한 애굽의 왕 바로느고의 군대에 대한 말씀이라',20048),
('jer-46-3','jer','예레미야',46,3,'너희는 작은 방패와 큰 방패를 예비하고 나가서 싸우라',20049),
('jer-46-4','jer','예레미야',46,4,'너희 기병이여 말에 안장을 지워 타며 투구를 쓰고 나서며 창을 갈며 갑옷을 입으라',20050),
('jer-46-5','jer','예레미야',46,5,'여호와의 말씀이니라 내가 본즉 그들이 놀라 물러가며 그들의 용사는 패하여 황급히 도망하며 뒤를 돌아보지 아니함은 어찜이냐 두려움이 그들의 사방에 있음이로다',20051),
('jer-46-6','jer','예레미야',46,6,'발이 빠른 자도 도망하지 못하며 용사도 피하지 못하고 그들이 다 북쪽에서 유브라데 강 가에 넘어지며 엎드러지는도다',20052),
